// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.di/** * NOUS — Boot initializer priority. * * Lower `order` value = runs earlier. Used by `AppInitializers` to sort * the `Set<AppInitializer>` multibinding before running. * * Lives in `:core:di` so feature modules can reference it without depending * on `:app`. */enum class Priority(val order: Int) {    /** Runs first — app cannot proceed without these. Must be blocking + idempotent. */    CRITICAL(0),    /** Runs after critical — important setup that should complete before UI. */    HIGH(1),    /** Runs in normal background order — most feature initializers go here. */    NORMAL(2),    /** Runs last — optional / can be deferred until idle. */    LAZY(3),}